<div class="card"><h2>2. Assign fee to class / section</h2><p class="muted">The assignment uses GegoK12's academic enrollment record, not student names. This is what makes bulk generation safe when students have similar names.</p><form method="POST" action="{{ route('tagore.fees.manage.assignment') }}">@csrf<div class="grid"><div class="field"><label>Fee structure</label><select name="fee_structure_id" required><option value="">Select structure</option>@foreach($structures as $f)<option value="{{ $f->id }}">{{ $f->name }} — {{ $f->institution }} @if($f->academic_year) — {{ $f->academic_year }}@endif</option>@endforeach</select></div><div class="field"><label>Class / section / stream</label><select name="standard_link_id" required><option value="">Select class/section</option>@foreach($classSections as $c)<option value="{{ $c->id }}">{{ $c->school }} — {{ $c->standard }} / {{ $c->section }}@if($c->stream) — {{ $c->stream }}@endif @if($c->academic_year) — {{ $c->academic_year }}@endif</option>@endforeach</select></div></div><button class="btn primary" style="margin-top:12px">Assign fee structure</button></form></div>
<div class="card"><h2>3. Preview & generate bulk demand</h2><form method="POST" action="{{ route('tagore.fees.manage.bulk.preview') }}">@csrf<div class="grid"><div class="field"><label>Assigned class / section</label><select name="assignment_id" required><option value="">Select assignment</option>@foreach($assignments as $a)<option value="{{ $a->id }}">{{ $a->institution }} — {{ $a->standard }} / {{ $a->section }}@if($a->stream) — {{ $a->stream }}@endif — {{ $a->fee_structure }} @if($a->academic_year) — {{ $a->academic_year }}@endif</option>@endforeach</select></div></div><button class="btn" style="margin-top:12px">Preview eligible students</button></form>
