<script>let n=1;function addHead(){const d=document.createElement('div');d.className='head';d.innerHTML=`<div class="field"><label>Fee head</label><input name="heads[${n}][name]" required></div><div class="field"><label>Code</label><input name="heads[${n}][code]" required></div><div class="field"><label>Amount</label><input name="heads[${n}][amount]" type="number" step="0.01" min="0" required></div><div class="field"><label>Category</label><input name="heads[${n}][category]"></div><button type="button" class="btn" onclick="this.parentElement.remove()">Remove</button>`;document.getElementById('heads').appendChild(d);n++}</script></body></html>